dashboard.definition:
{
	"title": "Hybrid Mesh Firewalling",
	"description": "Secure Networking drill-down dashboard for Hybrid Mesh Firewalling.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#0f172a",
				"strokeColor": "rgba(148,163,184,0.22)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Hybrid Mesh Firewalling",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/hybrid-mesh-firewalling.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e2e8f0",
				"markdown": "# Hybrid Mesh Firewalling\nFirewall enforcement, SSE controls, FMC policy activity, and data-loss findings across the hybrid mesh."
			}
		},
		"viz_hmf_fw_blocked": {
			"type": "splunk.singlevalue",
			"title": "Blocked Connections",
			"dataSources": {
				"primary": "ds_hmf_fw_blocked"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('blocked') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#f59e0b"
			}
		},
		"viz_hmf_ftd_feed": {
			"type": "splunk.singlevalueradial",
			"title": "FTD Feed Age",
			"dataSources": {
				"primary": "ds_hmf_ftd_feed"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('age_minutes') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('age_minutes') | lastPoint() | rangeValue(staleness)",
				"unit": "min"
			},
			"context": {
				"staleness": [
					{
						"to": 30,
						"value": "#16a34a"
					},
					{
						"from": 30,
						"to": 90,
						"value": "#eab308"
					},
					{
						"from": 90,
						"value": "#dc2626"
					}
				]
			}
		},
		"viz_hmf_fmc_count": {
			"type": "splunk.singlevalue",
			"title": "FMC Firewalls",
			"dataSources": {
				"primary": "ds_hmf_fmc_count"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('firewall_count') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#0ea5e9"
			}
		},
		"viz_hmf_sse_total": {
			"type": "splunk.singlevalue",
			"title": "SSE Security Events",
			"dataSources": {
				"primary": "ds_hmf_sse_total"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('total_events') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#14b8a6"
			}
		},
		"viz_hmf_unified_blocks": {
			"type": "splunk.line",
			"title": "Unified Blocks Trend",
			"dataSources": {
				"primary": "ds_hmf_unified_blocks"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#dc2626",
					"#f59e0b",
					"#0ea5e9",
					"#7c3aed"
				],
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_hmf_fmc_activity": {
			"type": "splunk.area",
			"title": "FMC Activity Trend",
			"dataSources": {
				"primary": "ds_hmf_fmc_activity"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#16a34a",
					"#dc2626",
					"#0ea5e9",
					"#64748b"
				],
				"stackMode": "stacked",
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			}
		},
		"viz_hmf_dns_categories": {
			"type": "splunk.bar",
			"title": "SSE DNS Blocked Categories",
			"dataSources": {
				"primary": "ds_hmf_dns_categories"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#dc2626",
					"#f59e0b",
					"#7c3aed"
				]
			}
		},
		"viz_hmf_enforcement_coverage": {
			"type": "splunk.table",
			"title": "Enforcement Coverage by Site",
			"dataSources": {
				"primary": "ds_hmf_enforcement_coverage"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		},
		"viz_hmf_fmc_top_rules": {
			"type": "splunk.bar",
			"title": "Top FMC Access Rule Hits",
			"dataSources": {
				"primary": "ds_hmf_fmc_top_rules"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#f59e0b",
					"#0ea5e9"
				]
			}
		},
		"viz_hmf_dlp_findings": {
			"type": "splunk.table",
			"title": "Secure Access DLP Findings",
			"dataSources": {
				"primary": "ds_hmf_dlp_findings"
			},
			"options": {
				"backgroundColor": "#0f172a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			}
		}
	},
	"dataSources": {
		"ds_hmf_fw_blocked": {
			"name": "Executive - Firewall Blocked Count",
			"options": {
				"ref": "executive_dashboard_firewall_blocked_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_ftd_feed": {
			"name": "Feed Monitor - FTD Firewall - Stream Staleness - Signal Rail KPI",
			"options": {
				"ref": "feed_monitor_ftd_firewall_staleness",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_fmc_count": {
			"name": "Secure Networking chain - FMC firewall count",
			"options": {
				"ref": "secure_networking_infra_fmc_firewall_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_sse_total": {
			"name": "Secure Networking - SSE Total Security Events",
			"options": {
				"ref": "secure_networking_sse_total_security_events",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_unified_blocks": {
			"name": "Secure Networking - HMF Unified Blocks Trend",
			"options": {
				"ref": "secure_networking_hmf_unified_blocks_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_fmc_activity": {
			"name": "Secure Networking chain - FMC activity trend",
			"options": {
				"ref": "secure_networking_fmc_activity_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_dns_categories": {
			"name": "Secure Networking - SSE DNS Blocked Categories",
			"options": {
				"ref": "secure_networking_sse_dns_blocked_categories",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_enforcement_coverage": {
			"name": "Secure Networking - HMF Enforcement Coverage by Site",
			"options": {
				"ref": "secure_networking_hmf_enforcement_coverage_by_site",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_fmc_top_rules": {
			"name": "Secure Networking chain - FMC top rules",
			"options": {
				"ref": "secure_networking_fmc_top_rules_hit",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_dlp_findings": {
			"name": "Secure Networking - Secure Access DLP Findings",
			"options": {
				"ref": "secure_networking_secure_access_dlp_findings",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#020617",
					"display": "auto-scale",
					"height": 1490,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 9,
							"w": 72,
							"h": 72
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 120,
							"y": 0,
							"w": 1300,
							"h": 90
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_fw_blocked",
						"position": {
							"x": 20,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_ftd_feed",
						"position": {
							"x": 375,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_fmc_count",
						"position": {
							"x": 730,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_sse_total",
						"position": {
							"x": 1085,
							"y": 110,
							"w": 335,
							"h": 180
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_unified_blocks",
						"position": {
							"x": 20,
							"y": 310,
							"w": 690,
							"h": 340
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_fmc_activity",
						"position": {
							"x": 730,
							"y": 310,
							"w": 690,
							"h": 340
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_dns_categories",
						"position": {
							"x": 20,
							"y": 670,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_enforcement_coverage",
						"position": {
							"x": 730,
							"y": 670,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_fmc_top_rules",
						"position": {
							"x": 20,
							"y": 1080,
							"w": 690,
							"h": 390
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_dlp_findings",
						"position": {
							"x": 730,
							"y": 1080,
							"w": 690,
							"h": 390
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
